package com.flashsale.coupon;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class UserCouponStateMachineTest{@Test void legalTransitions(){var m=new UserCouponStateMachine();assertEquals(UserCouponStatus.RESERVED,m.reserve(UserCouponStatus.AVAILABLE));assertEquals(UserCouponStatus.CONSUMED,m.consume(UserCouponStatus.RESERVED));assertEquals(UserCouponStatus.AVAILABLE,m.release(UserCouponStatus.RESERVED,true));assertEquals(UserCouponStatus.EXPIRED,m.release(UserCouponStatus.RESERVED,false));}@Test void illegalTransitionRejected(){assertThrows(IllegalArgumentException.class,()->new UserCouponStateMachine().consume(UserCouponStatus.AVAILABLE));}}
